	rec := httptest.NewRecorder()
	router.ServeHTTP(rec, req)
	return rec
}

func TestUpdateWeightReplacesOnlyWeightFromBody(t *testing.T) {
	router, st := testRouter(t)
	registerInstance(t, router, weightRecord())

	rec := doRequest(t, router, http.MethodPut,
		"/api/v1/services/svc/instances/i-1/weight",
		map[string]any{"weight": "25.5"})
	if rec.Code != http.StatusOK {
		t.Fatalf("status = %d body %s", rec.Code, rec.Body.String())
	}
	instance := decodeBody(t, rec)["instance"].(map[string]any)
	if instance["service_name"] != "svc" || instance["instance_id"] != "i-1" ||
		instance["address"] != "10.0.0.8:8080" || instance["port"].(float64) != 8080 ||
		instance["healthy"] != true {
		t.Fatalf("non-weight fields changed: %v", instance)
	}
	if instance["weight"].(float64) != 25.5 {
		t.Fatalf("weight = %v, want 25.5", instance["weight"])
	}
	if instance["heartbeat_at"] != baseTime {
		t.Fatalf("heartbeat_at = %v, want %s", instance["heartbeat_at"], baseTime)
	}

	got, found, err := st.GetInstance("svc", "i-1")
	if err != nil || !found {
		t.Fatalf("get: found=%v err=%v", found, err)
	}
	if got.Weight != 25.5 || got.Address != "10.0.0.8:8080" || got.Port != 8080 ||
		!got.Healthy || !got.HeartbeatAt.Equal(mustParseTime(baseTime)) {
		t.Fatalf("stored record changed beyond weight: %+v", got)
	}
}

func TestUpdateWeightAcceptsQueryAndBodyWins(t *testing.T) {
	router, _ := testRouter(t)
	registerInstance(t, router, weightRecord())

	rec := doRequest(t, router, http.MethodPut,
		"/api/v1/services/svc/instances/i-1/weight?weight=3",
		map[string]any{"weight": 42})
	if rec.Code != http.StatusOK {
		t.Fatalf("status = %d body %s", rec.Code, rec.Body.String())
	}
	instance := decodeBody(t, rec)["instance"].(map[string]any)
	if instance["weight"].(float64) != 42 {
		t.Fatalf("body must win over query: weight = %v", instance["weight"])
	}

	rec = doRequest(t, router, http.MethodPut,
		"/api/v1/services/svc/instances/i-1/weight?weight=7", nil)
	if rec.Code != http.StatusOK {
		t.Fatalf("status = %d body %s", rec.Code, rec.Body.String())
	}
	instance = decodeBody(t, rec)["instance"].(map[string]any)
	if instance["weight"].(float64) != 7 {
		t.Fatalf("query weight = %v, want 7", instance["weight"])
	}
}

