func TestUpdateWeightInvalidRequests(t *testing.T) {
	router, st := testRouter(t)
	registerInstance(t, router, weightRecord())

	cases := []struct {
		name string
		path string
		body any
	}{
		{"missing weight", "/api/v1/services/svc/instances/i-1/weight", map[string]any{}},
		{"unparseable weight", "/api/v1/services/svc/instances/i-1/weight", map[string]any{"weight": "heavy"}},
		{"zero weight", "/api/v1/services/svc/instances/i-1/weight", map[string]any{"weight": 0}},
		{"negative weight", "/api/v1/services/svc/instances/i-1/weight", map[string]any{"weight": -1}},
		{"string zero", "/api/v1/services/svc/instances/i-1/weight", map[string]any{"weight": "0"}},
		{"boolean weight", "/api/v1/services/svc/instances/i-1/weight", map[string]any{"weight": true}},
		{"empty service name", "/api/v1/services//instances/i-1/weight", map[string]any{"weight": 5}},
		{"empty instance id", "/api/v1/services/svc/instances//weight", map[string]any{"weight": 5}},
		{"query zero weight", "/api/v1/services/svc/instances/i-1/weight?weight=0", nil},
		{"query non numeric weight", "/api/v1/services/svc/instances/i-1/weight?weight=nope", nil},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			rec := doRequest(t, router, http.MethodPut, tc.path, tc.body)
			expectErrorShape(t, rec, http.StatusBadRequest, "invalid_parameter")
			got, found, _ := st.GetInstance("svc", "i-1")
